mapper.select:
SELECT 
FROM ai_command_runs
WHERE 1 = 1

    AND server_id = #{serverId}


    AND status = #{status}

ORDER BY id DESC

mapper.update:
UPDATE ai_command_runs
SET status = 'approved', approver_id = #{approverId}
WHERE id = #{id}
  AND status = 'pending_approval'
  AND (expires_at IS NULL OR expires_at > #{now})

UPDATE ai_command_runs
SET status = 'rejected', approver_id = #{approverId}, completed_at = #{now}
WHERE id = #{id}
  AND status = 'pending_approval'

UPDATE ai_command_runs
SET status = 'failed', error_code = #{errorCode}, completed_at = #{now}
WHERE id = #{id}
  AND status = 'pending_approval'

UPDATE ai_command_runs
SET status = #{finalStatus}, result_json = #{resultJson}, exit_code = #{exitCode},
    truncated = #{truncated}, duration_ms = #{durationMs}, error_code = #{errorCode},
    completed_at = #{now}
WHERE execution_id = #{executionId}
  AND status IN ('approved', 'executing')

mapper.select:
SELECT id
FROM ai_command_runs
WHERE status = 'executing'
  AND updated_at < #{threshold}
ORDER BY id
LIMIT #{batchSize}

